import {HttpFirstLoopRuns} from '../src/first-loop/native-client';
import {nativeRequestFingerprint} from '../src/first-loop/native-recovery';
const target={ip:'10.0.0.1',apiServerKey:'synthetic-secret'};
describe('official Hermes runs adapter',()=>{
 it('matches the pinned Python fingerprint for the full ordinary API body, including Unicode and escaped text',()=>{
  // Independent hashlib/json.dumps oracle from Hermes a28a5d03, not a hash
  // generated by the production helper under test.
  expect(nativeRequestFingerprint('saleads-flow-fixture','Español 😀\n"quoted"\\slash\t\u0001','Trusted policy / line\nnext'))
   .toBe('05d4747375322e0e7317c1a57ff4673851faa17dedd5e7347e24107949502d13');
 });
 it('uses native input/session/instructions and durable idempotency without model override',async()=>{const fetcher=jest.fn(async()=>new Response(JSON.stringify({run_id:'run_1',status:'queued',replayed:false}),{status:202}));const c=new HttpFirstLoopRuns(fetcher);await c.start(target,'flow_1','owner data','trusted context','first-loop-id');const [url,request]=fetcher.mock.calls[0]! as unknown as [string,RequestInit];expect(url).toBe('http://10.0.0.1:8642/v1/runs');expect(JSON.parse(String(request.body))).toEqual({input:'owner data',session_id:'flow_1',instructions:'trusted context'});expect(request.headers).toMatchObject({'Idempotency-Key':'first-loop-id'});});
 it('rejects upstream failures and never returns raw error content',async()=>{const c=new HttpFirstLoopRuns(async()=>new Response('private upstream details',{status:403}));await expect(c.status(target,'run_1')).rejects.toMatchObject({code:'SERVICE_UNAVAILABLE'});});
 it('reads actual durable replay capability with GET and never guesses missing fields',async()=>{
  const calls:Array<{url:string;method:string}>=[];
  const c=new HttpFirstLoopRuns(async(url,options)=>{calls.push({url:String(url),method:options?.method??'GET'});return Response.json({features:{runs_idempotency:{supported:true,durable:true,retention_seconds:86400}}});});
  expect(await c.capabilities(target)).toEqual({supported:true,durable:true,retention_seconds:86400});
  expect(calls).toEqual([{url:'http://10.0.0.1:8642/v1/capabilities',method:'GET'}]);
  const invalid=new HttpFirstLoopRuns(async()=>Response.json({features:{runs_idempotency:{supported:true,durable:true,retention_seconds:'86400'}}}));
  expect(await invalid.capabilities(target)).toBeNull();
 });
});
